import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const root = new Group();
  root.name = config.id || 'collection-list-row';

  const timelines = [];
  const ownedResources = [];
  const handlers = {};

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const rowWidth = 5.8;
  const rowHeight = 0.82;

  const panelGeometry = new PlaneGeometry(rowWidth, rowHeight);
  const panelMaterial = new MeshBasicNodeMaterial({
    color: new Color(ink),
    transparent: true,
    opacity: 0.98
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.name = 'collection-row-panel';
  panel.position.z = 0;
  root.add(panel);
  ownedResources.push(panelGeometry, panelMaterial);

  const dividerGeometry = new PlaneGeometry(rowWidth, 0.012);
  const dividerMaterial = new MeshBasicNodeMaterial({
    color: new Color(paper),
    transparent: true,
    opacity: 0.18
  });
  const divider = new Mesh(dividerGeometry, dividerMaterial);
  divider.name = 'collection-row-divider';
  divider.position.set(0, -rowHeight * 0.5 + 0.025, 0.012);
  root.add(divider);
  ownedResources.push(dividerGeometry, dividerMaterial);

  const edgeGeometry = new PlaneGeometry(0.035, rowHeight * 0.72);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color(accent),
    transparent: true,
    opacity: 0
  });
  const edge = new Mesh(edgeGeometry, edgeMaterial);
  edge.name = 'collection-row-focus-edge';
  edge.position.set(-rowWidth * 0.5 + 0.045, 0, 0.018);
  root.add(edge);
  ownedResources.push(edgeGeometry, edgeMaterial);

  const textGroup = new Group();
  textGroup.name = 'collection-row-text';
  textGroup.position.set(-rowWidth * 0.5 + 0.28, 0, 0.025);
  root.add(textGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role || 'body';
    const fontSize =
      item.typography?.fontSize ??
      (role === 'headline' || role === 'title' ? 0.34 :
        role === 'subhead' ? 0.2 :
          role === 'caption' || role === 'meta' ? 0.09 : 0.13);

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: role === 'meta' || role === 'caption' ? paper : paper,
      align: item.align || 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.y =
      role === 'meta' || role === 'caption' ? -0.16 : 0.08;
    textGroup.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!root.parent && root.userData.cleaned) return;
      panelMaterial.map = texture;
      panelMaterial.color = new Color(surface);
      panelMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const baseY = root.position.y;
  const baseScale = root.scale.clone();

  handlers.hover = (active = true) => {
    const targetY = active ? baseY + 0.15 : baseY;
    const targetZ = active ? 0.035 : 0;
    const targetOpacity = active ? 0.72 : 0;

    const timeline = gsap.timeline({
      defaults: { overwrite: true, ease: 'power3.out' }
    });
    timeline.to(root.position, { y: targetY, z: targetZ, duration: 0.32 }, 0);
    timeline.to(edgeMaterial, { opacity: targetOpacity, duration: 0.24 }, 0);
    timelines.push(timeline);
  };

  handlers.focus = () => {
    const timeline = gsap.to(edgeMaterial, {
      opacity: 1,
      duration: 0.2,
      ease: 'power2.out',
      overwrite: true
    });
    timelines.push(timeline);
  };

  handlers.blur = () => {
    const timeline = gsap.to(edgeMaterial, {
      opacity: 0,
      duration: 0.2,
      ease: 'power2.out',
      overwrite: true
    });
    timelines.push(timeline);
  };

  handlers.click = () => {
    const timeline = gsap.timeline({
      defaults: { overwrite: true }
    });
    timeline.to(root.scale, {
      x: baseScale.x * 0.97,
      y: baseScale.y * 0.97,
      z: baseScale.z * 0.97,
      duration: 0.12,
      ease: 'power2.out'
    });
    timeline.to(root.scale, {
      x: baseScale.x,
      y: baseScale.y,
      z: baseScale.z,
      duration: 0.32,
      ease: 'back.out(2)'
    });
    timelines.push(timeline);
    ctx.emit('hub-collection.select', {
      id: config.id,
      node: root
    });
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    root.traverse((object) => {
      if (object.geometry && !ownedResources.includes(object.geometry)) {
        object.geometry.dispose();
      }
      if (object.material && !ownedResources.includes(object.material)) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) material.dispose();
      }
    });

    for (const resource of ownedResources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }
  };

  return root;
}
